function counterBench(){
  const nodes=[],edges=[];
  const add=(id,type,x,y,label,extra={})=>nodes.push(designNode(id,type,x,y,{label,...extra}));
  const out=(node,index=0)=>({node,side:'out',index}),input=(node,index=0)=>({node,side:'in',index});
  const link=(from,to,style='normal',color='White')=>edges.push({from,to,style,color});
  add('count','button',0,96,'COUNT +1');add('reset','button',0,432,'RESET → 00');
  add('notResetButton','inverter',192,432,'Reset released');
  add('clearReset','and',384,432,'At zero AND released');
  add('resetMemory','buffer1',576,432,'Reset in progress',{bit:false});
  add('notReset','inverter',384,96,'Count enabled');
  add('manual','and',576,96,'Manual count');
  add('notZero','inverter',192,720,'Not at zero');
  add('resetRun','and',384,720,'Keep resetting');
  add('clock','and',576,720,'Reset pulse');
  add('clockDelay','delay',816,720,'Reset clock · 1',{delay:1});
  add('notClock','inverter',816,960,'Clock feedback');
  add('advance','or',1008,96,'Count OR reset pulse');
  add('counter','selector16',1200,96,'Counter positions 0–15',{channel:0});
  link(out('reset'),input('resetMemory',1));link(out('reset'),input('notResetButton'));
  link(out('notResetButton'),input('clearReset',1));link(out('counter',0),input('clearReset'));
  link(out('clearReset'),input('resetMemory',0));link(out('resetMemory'),input('notReset'));
  link(out('count'),input('manual'));link(out('notReset'),input('manual',1));
  link(out('manual'),input('advance'));link(out('clock'),input('advance',1));link(out('advance'),input('counter'));
  link(out('counter',0),input('notZero'));link(out('resetMemory'),input('resetRun'));
  link(out('notZero'),input('resetRun',1));link(out('resetRun'),input('clock'));
  link(out('notClock'),input('clock',1));link(out('clock'),input('clockDelay'));
  link(out('clockDelay'),input('notClock'));link(out('resetMemory'),{x:768,y:552},'neon','Orange');
  for(let bit=0;bit<4;bit++){
    const y=432+bit*336,channels=Array.from({length:16},(_,i)=>i).filter(i=>i&(1<<bit));
    let sources=channels.map(i=>out('counter',i));
    for(let level=0;sources.length>1;level++){
      const next=[];
      for(let i=0;i<sources.length;i+=2){
        const id=`encode${bit}-${level}-${i/2}`,x=1200+level*576;
        add(id,'or',x+i/2*144,y,level===2?`Bit ${2**bit}`:'');
        link(sources[i],input(id));link(sources[i+1],input(id,1));next.push(out(id));
      }
      sources=next;
    }
    link(sources[0],{x:2688,y:y+48},'neon','Cyan');
    link(sources[0],input('bcd',3-bit));
  }
  add('bcd','binaryBCD',1728,1872,'Count → decimal');
  for(const [digit,x] of [['tens',2352],['units',2544]]){
    add(digit,'converter7',x,1872,'');add(digit+'Display','display7',x,1872,digit==='tens'?'Count · tens':'Count · units');
    for(let i=0;i<4;i++)link(out('bcd',(digit==='tens'?0:4)+i),input(digit,i));
  }
  // More room between functional sections and OR stages for distinct signal lanes.
  nodes.forEach(n=>{n.x=Math.round(n.x*1.5/CIRCUIT_GRID)*CIRCUIT_GRID;n.y=Math.round(n.y*1.5/CIRCUIT_GRID)*CIRCUIT_GRID;});
  edges.forEach(e=>{for(const p of [e.from,e.to])if(!p.node){p.x*=1.5;p.y*=1.5;}});
  return {id:'counter-0-15',name:'Counter · 0–15 with reset',
    detail:'Press COUNT +1 once per count. The selector stores 0–15; OR gates encode four binary bits and the screens display 00–15. After 15, the next press returns to 00.',
    check:'Press RESET and wait for the orange reset-in-progress wire to go dark before counting again. Reset steps forward to 00 in at most six seconds. All gates, timing parts, memory and wires are editable. Leave all 16 selector channels enabled.',
    nodes,wires:presetDesignWires(nodes,edges,'counter')};
}
