function largeAdderBench(){
  const offset=2304,copy=(prefix,dy)=>{
    const part=structuredClone(calculatorTemplate);
    for(const n of part.nodes){n.id=prefix+n.id;n.y+=dy;
      if(prefix==='high-'&&n.label){
        n.label=n.label.replace(/· (1|2|4|8)(?!\d)/g,(_,weight)=>`· ${Number(weight)*16}`)
          .replace('Carry · +16','Carry · +256').replace('Mismatch · carry 16','Mismatch · carry 256')
          .replace('Lower four bits','Upper four bits').replace('Low bits','High bits');
      }}
    for(const w of part.wires){w.id=prefix+w.id;
      for(const end of [w.from,w.to]){if(end.node)end.node=prefix+end.node;else end.y+=dy;}
      w.points.forEach(p=>p.y+=dy);}
    return part;
  };
  const low=copy('low-',0),high=copy('high-',offset);
  const from={node:'low-c3',side:'out',index:0};
  const bridges=[
    designWire('carry-to-high-sum',from,{node:'high-s0',side:'in',index:1},[{x:1392,y:1296},{x:1392,y:2256},{x:648,y:2256},{x:648,y:2472}]),
    designWire('carry-to-high-generate',from,{node:'high-h0',side:'in',index:1},[{x:1404,y:1296},{x:1404,y:2268},{x:636,y:2268},{x:636,y:2616}]),
    designWire('carry-to-high-reference',from,{node:'high-reference',side:'in',index:8},[{x:1416,y:1296},{x:1416,y:2280},{x:-96,y:2280},{x:-96,y:4080}])
  ];
  return {id:'eight-bit-adder-bench',name:'8-bit ripple adder · reference checks',
    detail:'Sixteen levers supply two eight-bit numbers. Two four-bit gate-level stages are linked by a carry wire; two built-in Full Adders independently check every result bit. Upper block covers weights 1–8, lower block covers weights 16–128.',
    check:'Try 15+1 → 16, 255+1 → 256, and 255+255 → 510. Cyan wires show eight sum bits, the intermediate carry, and final carry. All ten red mismatch wires should remain dark. Each block also displays its four result bits as a decimal nibble.',
    nodes:[...low.nodes,...high.nodes],wires:[...low.wires,...high.wires,...bridges]};
}
