function addMagnitudeComparator({add,out,input,link},bits){
  let previous=null;
  for(let bit=bits-1;bit>=0;bit--){
    const row=(bits-1-bit)*480;
    add('a'+bit,'lever',0,row,`A · ${2**bit}`);
    add('b'+bit,'lever',144,row,`Threshold · ${2**bit}`);
    add('notA'+bit,'inverter',336,row+288,`NOT A${bit}`);
    add('notB'+bit,'inverter',336,row+144,`NOT B${bit}`);
    add('equalBit'+bit,'xnor',528,row,`Bit ${2**bit} equal`);
    add('greaterBit'+bit,'and',528,row+144,`A bit ${2**bit} higher`);
    add('lessBit'+bit,'and',528,row+288,`A bit ${2**bit} lower`);
    link(out('a'+bit),input('notA'+bit));link(out('b'+bit),input('notB'+bit));
    link(out('a'+bit),input('equalBit'+bit));link(out('b'+bit),input('equalBit'+bit,1));
    link(out('a'+bit),input('greaterBit'+bit));link(out('notB'+bit),input('greaterBit'+bit,1));
    link(out('notA'+bit),input('lessBit'+bit));link(out('b'+bit),input('lessBit'+bit,1));
    if(!previous){previous={equal:'equalBit'+bit,greater:'greaterBit'+bit,less:'lessBit'+bit};continue;}
    add('equalThrough'+bit,'and',768,row,'All higher bits equal');
    add('greaterCandidate'+bit,'and',768,row+144,'Higher bits equal AND this bit greater');
    add('lessCandidate'+bit,'and',768,row+288,'Higher bits equal AND this bit lower');
    add('greaterThrough'+bit,'or',1008,row+144,'A greater so far');
    add('lessThrough'+bit,'or',1008,row+288,'A lower so far');
    link(out(previous.equal),input('equalThrough'+bit));link(out('equalBit'+bit),input('equalThrough'+bit,1));
    link(out(previous.equal),input('greaterCandidate'+bit));
    link(out('greaterBit'+bit),input('greaterCandidate'+bit,1));
    link(out(previous.equal),input('lessCandidate'+bit));
    link(out('lessBit'+bit),input('lessCandidate'+bit,1));
    link(out(previous.greater),input('greaterThrough'+bit));
    link(out('greaterCandidate'+bit),input('greaterThrough'+bit,1));
    link(out(previous.less),input('lessThrough'+bit));
    link(out('lessCandidate'+bit),input('lessThrough'+bit,1));
    previous={equal:'equalThrough'+bit,greater:'greaterThrough'+bit,less:'lessThrough'+bit};
  }
  return previous;
}
