  const alphabetInput=alphabet&&time(alphabet.nextAt)?{activeGroup,queue:Array.isArray(alphabet.queue)?alphabet.queue.filter(id=>byId.get(id)?.alphabet&&byId.get(id).type==='button'):[],nextAt:alphabet.nextAt}:null;
  const calculatorInput=new Map(Array.isArray(raw.calculatorInput)?raw.calculatorInput.flatMap(pair=>{
    if(!Array.isArray(pair)||pair.length!==2||typeof pair[0]!=='string'||!pair[1]||!time(pair[1].nextAt))return [];
    const queue=Array.isArray(pair[1].queue)?pair[1].queue.filter(id=>byId.get(id)?.calculator?.group===pair[0]&&byId.get(id).type==='button'):[];
    return [[pair[0],{queue,nextAt:pair[1].nextAt}]];
  }):[]);
