  const ids=new Set(selectedWires),ports=model.nodes.filter(n=>selectedNodes.has(n.id)).flatMap(n=>['in','out'].flatMap(side=>PARTS[n.type][side==='in'?'inputs':'outputs'].map((_,i)=>portPosition(n,side,i))));
