      const label=document.createElement('span');label.className='part-tile-name';label.textContent=name;
      button.append(wirePreview(style),label);
      button.setAttribute('aria-pressed',String(Boolean(wireStyle===style&&(wirePlacementArmed||draft&&!draft.editing&&!draft.junction))));
      button.title=`Select ${name.toLowerCase()} to start on empty canvas; click to add bends, then Enter for a loose end`;
      button.onclick=()=>selectWireTool(style);
