  selectedNodes=new Set(g.baseNodes);selectedWires=new Set(g.baseWires);
  for(const id of hits.nodes)selectedNodes.has(id)?selectedNodes.delete(id):selectedNodes.add(id);
  for(const id of hits.wires)selectedWires.has(id)?selectedWires.delete(id):selectedWires.add(id);
