    const title=document.createElement('h4');title.textContent=design.name;
    const info=document.createElement('div');info.className='design-info';
    const infoButton=document.createElement('button');infoButton.type='button';infoButton.className='design-info-button';infoButton.textContent='i';infoButton.setAttribute('aria-label',`About ${design.name}`);
    const tooltip=document.createElement('div');tooltip.className='design-tooltip';tooltip.id=`design-info-${design.id}`;tooltip.setAttribute('role','tooltip');infoButton.setAttribute('aria-describedby',tooltip.id);
    const detail=document.createElement('p');detail.textContent=design.detail;tooltip.append(detail);
    if(design.check){const check=document.createElement('p');check.textContent=design.check;tooltip.append(check);}
    if(design.source){const reference=document.createElement('a');reference.href=design.source;reference.target='_blank';reference.rel='noopener noreferrer';reference.textContent=design.sourceLabel||'Reference';reference.className='design-reference';tooltip.append(reference);}
    info.append(infoButton,tooltip);
    const cardHead=document.createElement('div');cardHead.className='design-card-head';cardHead.append(title,info);
    const preview=document.createElement('img');preview.className='design-preview';preview.alt=`Full circuit preview: ${design.name}`;preview.loading='lazy';scheduleDesignPreview(preview,design,list);
    const previewWrap=document.createElement('div');previewWrap.className='design-preview-wrap';previewWrap.append(preview);
    const button=document.createElement('button');button.type='button';button.className='design-add';button.innerHTML='<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M8 3v10M3 8h10"/></svg>Add to canvas';button.setAttribute('aria-label',`Add ${design.name} to canvas`);button.onclick=()=>addDesign(design);
    const meta=document.createElement('span');meta.className='design-meta';meta.textContent=`${design.nodes.length} parts · ${design.wires.length} wires`;
    const foot=document.createElement('div');foot.className='design-card-foot';foot.append(meta,button);
    const body=document.createElement('div');body.className='design-card-body';body.append(cardHead,foot);
