  if(typeof ResizeObserver!=='undefined')new ResizeObserver(entries=>{const rect=entries[0].contentRect;viewportSize={w:rect.width,h:rect.height};updateRenderWindow(true);}).observe(els.viewport);
  $('tidy-wires').onclick=tidyWires;
  els['part-search'].addEventListener('input',renderPalette);
  let naming=false;
