  $('close-files').onclick=()=>$('file-dialog').close();
  $('file-dialog').addEventListener('keydown',e=>e.stopPropagation());
  $('export-project').onclick=()=>{exportProject();$('file-message').textContent='Download requested. Check your browser’s downloads.';$('file-message').hidden=false;};
  $('import-project').onclick=()=>{$('file-message').hidden=true;els['import-file'].click();};
  els['import-file'].onchange=async()=>{const f=els['import-file'].files?.[0];if(!f)return;try{const data=normalize(JSON.parse(await f.text()));if(!valid(data))throw Error('Invalid circuit file');newProject({name:data.name,nodes:data.nodes,wires:data.wires});$('file-dialog').close();}catch{$('file-message').textContent='Could not open this file. Choose a valid circuit JSON file.';$('file-message').hidden=false;}els['import-file'].value='';};
