  $('wire-paint').onclick=()=>{if(selectionSize()!==1||selected?.kind!=='wire')return;paintOpen=!paintOpen;renderWirePaint();};
  document.addEventListener('pointerdown',e=>{if(paintOpen&&!e.target.closest('#wire-paint-control')){paintOpen=false;renderWirePaint();}});
  document.addEventListener('pointerdown',e=>{if(wirePointMenu&&!e.target.closest('#wire-point-menu'))closeWirePointMenu();},true);
  document.addEventListener('wheel',()=>closeWirePointMenu(),{capture:true,passive:true});
  window.addEventListener('resize',()=>closeWirePointMenu());
